S('0217',"تعليمات الدراسة الخاصة",[
("rule",[1],"المادة 3","يجوز أن يقبل في الدراسة الخاصة الطلبة الذين يرغبون بالدراسة وفق الفئات التالية: الطلبة الذين يدرسون في جامعات أو معاهد جامعية عليا داخل الأردن أو خارجه أو خريجي هذه الجامعات والمعاهد ويرغبون بدراسة مساقات في الجامعة لفصل دراسي واحد أو أكثر لأغراض استكمال متطلبات تخرجهم أو لأغراض الحصول على شهادة مزاولة المهنة أو معادلة الشهادة؛ والأفراد الذين يرغبون في تعميق معرفتهم التخصصية بهدف تحسين أدائهم ومهاراتهم في الأعمال أو الوظائف التي يقومون بها، أو الذين يرغبون في إثراء معرفتهم الثقافية أو العلمية؛ والطلبة الذين يرغبون بالالتحاق في الجامعة مستقبلاً في مختلف الدرجات.",
 "من الفئات التي يقبل لها في برنامج الدراسة الخاصة؟","هل يمكن لخريج جامعة أخرى أن يسجل مساقات في الدراسة الخاصة؟","مين بقدر يدرس دراسة خاصة بالجامعة؟"),
("rule",[1],"المادة 4 و5","يشترط في قبول الطالب للالتحاق في الدراسة الخاصة أن يكون الطالب حاصلاً على شهادة الدراسة الثانوية العامة الأردنية أو ما يعادلها، وتوفر الشواغر في الشعب أو المساقات التي يرغب الطالب التسجيل بها في ذلك الفصل. ويطلب من الطالب تقديم كشف علامات شهادة الثانوية العامة أو ما يعادلها، وصورة عن هوية الأحوال المدنية للطالب الأردني أو صورة عن جواز السفر للطالب غير الأردني.",
 "ما شروط القبول في الدراسة الخاصة؟","ما الوثائق المطلوبة للتسجيل في الدراسة الخاصة؟","شو الأوراق المطلوبة للدراسة الخاصة؟"),
("rule",[1],"المادة 6 و7 و8","يقدم الطالب طلب القبول مبيناً فيه المساقات التي يرغب بتسجيلها إلى عميد الكلية / عميد كلية الدراسات العليا (لطلبة الدراسات العليا)، ويبلغ العميد المعني الطالب والمسجل العام بقراره. ويتم تسجيل المساقات حسب إجراءات التسجيل المعتمدة بعد استكمال إجراءات القبول، ولا تنطبق متطلبات الخطة الدراسية على طلبة الدراسة الخاصة. وتستوفى الرسوم الجامعية ورسوم الخدمات للمساقات مساوية لرسوم طلبة البرنامج الموازي أو الدولي حسب التخصص والجنسية.",
 "كم رسوم الدراسة الخاصة مقارنة بالبرنامج الموازي؟","إلى من يقدم طلب القبول في الدراسة الخاصة؟","كم بدفع رسوم بالدراسة الخاصة؟"),
])

S('0228',"تعليمات البرنامج التحضيري الاختياري",[
("rule",[1],"المادة 2 و3","تطبق التعليمات على جميع الطلبة المقبولين والراغبين في الجامعة في تقوية معرفتهم من أجل تحسين مهارات اللغة الإنجليزية عندهم إلى المستوى المطلوب في المساقات التي تدرس باللغة الإنجليزية، وبطرح مساقات بأساسيات الرياضيات والفيزياء والكيمياء والأحياء. ويتكون البرنامج التحضيري من ثلاثة فصول دراسية (الأول + الثاني + الصيفي).",
 "ما هدف البرنامج التحضيري الاختياري؟","كم فصلاً دراسياً يتكون منه البرنامج التحضيري الاختياري؟","شو هو البرنامج التحضيري الاختياري؟"),
("rule",[1],"المادة 6 و8 و9","الطالب الملتحق بالبرنامج التحضيري له نفس حقوق باقي الطلبة وتطبق عليه تعليمات الجامعة، ولا يجوز للطالب تأجيل دراسته في البرنامج التحضيري، ولا يسمح للطالب في البرنامج التحضيري بالانسحاب من المواد ويعامل من يقوم بذلك معاملة الطالب الراسب في المادة.",
 "هل يجوز تأجيل الدراسة أو الانسحاب من المواد في البرنامج التحضيري الاختياري؟","هل لطالب البرنامج التحضيري نفس حقوق باقي الطلبة؟","بقدر أنسحب من مادة بالبرنامج التحضيري؟"),
("number",[1],"المادة 12 و14","يستطيع الطالب أن يسجل 15 ساعة معتمدة خلال الفصل الدراسي الأول و15 ساعة معتمدة خلال الفصل الدراسي الثاني و6 ساعات معتمدة خلال الفصل الدراسي الصيفي. ويعتبر الطالب ناجحاً في البرنامج التحضيري إذا أكمل جميع مواده بنجاح.",
 "كم ساعة معتمدة يسجل الطالب في كل فصل من البرنامج التحضيري؟","متى يعتبر الطالب ناجحاً في البرنامج التحضيري؟","كم ساعة بقدر أسجل بالبرنامج التحضيري بالفصل الأول وبالصيفي؟"),
("number",[1],"المادة 13","العلامة النهائية للمادة هي مجموع علامات الامتحان النهائي وعلامات الأعمال الفصلية، ويعقد الامتحان النهائي لكل مادة في نهاية الفصل ويخصص له 40% من العلامة النهائية للمادة، وتشمل الأعمال الفصلية لكل مادة امتحانين على الأقل ويخصص لها 60% من العلامة النهائية للمادة.",
 "كم نسبة الامتحان النهائي والأعمال الفصلية في مواد البرنامج التحضيري الاختياري؟","كيف تحسب العلامة النهائية لمادة في البرنامج التحضيري؟","كيف بتتوزع العلامات بالبرنامج التحضيري؟"),
("number",[1],"المادة 17","يعفى الطالب الحاصل على علامة (70%) فما فوق في أي مساق درسه في البرنامج التحضيري من دراسة المساق المناظر في السنة الأولى ويدخل في حساب معدل الطالب التراكمي. وإذا رسب طالب البرنامج التحضيري المبتعث من المملكة العربية السعودية في مساق علمي واحد أو أكثر وكان قبوله في تخصص الطب أو طب الأسنان يفصل من هذين التخصصين وعليه تغيير التخصص إلى تخصصات أخرى.",
 "ما العلامة التي تعفي الطالب من دراسة المساق المناظر بعد البرنامج التحضيري؟","هل تدخل علامة مساق البرنامج التحضيري في المعدل التراكمي إذا كانت 70% فأكثر؟","اذا جبت 70 بمساق تحضيري بنعفى من المناظر له؟"),
])

S('0234',"مدلول رموز وأرقام المساقات",[
("rule",[1],"الرقم","يستدل على أي مساق برمز مكون من حرفين ورقم مؤلف من ثلاث منازل: منزلة الآحاد (الفصل الدراسي للمساق): الفردي الفصل الدراسي الأول والزوجي الفصل الدراسي الثاني، ومنزلة العشرات (تخصص وموضوع المساق)، ومنزلة المئات (مستوى المساق من حيث طرحه في البرنامج الاسترشادي): 1 السنة الأولى و2 السنة الثانية و3 السنة الثالثة و4 السنة الرابعة و5 السنة الخامسة و6 السنة السادسة. والمساقات المطروحة في الفصل الدراسي الصيفي يعطى لها الرقم (9).",
 "ماذا تعني منازل رقم المساق في الجامعة؟","ماذا يعني رقم المئات في رقم المساق؟","شو يعني رقم المساق بالجامعة؟"),
("rule",[1],"الرقم","منزلة الآحاد في رقم المساق تدل على الفصل الدراسي: الرقم الفردي يعني الفصل الدراسي الأول، والرقم الزوجي يعني الفصل الدراسي الثاني، والمساقات المطروحة في الفصل الصيفي يعطى لها الرقم (9).",
 "ماذا يدل الرقم الفردي والزوجي في آخر رقم المساق؟","ما الرقم الذي يعطى للمساقات المطروحة في الفصل الصيفي؟","المساق اللي رقمه بينتهي بـ 9 صيفي؟"),
])

S('0236',"مدلول رقم الطالب",[
("rule",[1],"البند 1 و2","يتكون رقم الطالب من (11) خانة: الخانات الأربعة الأولى من اليسار عبارة عن سنة قبول الطالب، والخانة الخامسة من اليسار عبارة عن نوع البرنامج الذي قبل فيه الطالب: (0) البرنامج العادي، (1) البرنامج الموازي في عمان، (2) البرنامج الموازي في الجامعة، (3) برنامج الماجستير، (4) برنامج الاختصاص العالي، (5) برنامج الدبلوم، (6) برنامج الدكتوراه، (7) برنامج الدراسة الخاصة، (8) البرنامج الإضافي، (9) مقبول جامعات عراقية.",
 "من كم خانة يتكون رقم الطالب وماذا تمثل الخانات الأربع الأولى؟","ماذا تعني الخانة الخامسة في رقم الطالب؟","شو يعني رقم الطالب تبعي؟"),
("rule",[1],"البند 3 و4","الخانات السادسة والسابعة والثامنة من اليسار في رقم الطالب عبارة عن رقم التخصص، والخانات التاسعة والعاشرة والحادية عشر عبارة عن تسلسل رقم الطالب في ذلك التخصص.",
 "ماذا تمثل الخانات من السادسة إلى الثامنة في رقم الطالب؟","كيف يحدد تسلسل الطالب داخل التخصص في رقمه الجامعي؟","وين برقمي الجامعي رقم التخصص؟"),
])

S('0235',"مدلول أرقام الأسطر",[
("rule",[1],"البند 1","الخانة الأولى من اليمين في رقم السطر هي خانة تعريف للمساق: (0) المساق يطرح بهذا الرقم لأول مرة، (1) لثاني مرة، (2) لثالث مرة، (3) لرابع مرة، (4) لخامس مرة، (6) يطرح لرسالة الماجستير بواقع 9 ساعات معتمدة، (7) لرسالة الماجستير بواقع 6 ساعات معتمدة، (8) لرسالة الماجستير بواقع 3 ساعات معتمدة، (9) لرسالة الماجستير بواقع 0 ساعة معتمدة. والخانات الثانية والثالثة والرابعة من اليمين رقم المساق، والخامسة والسادسة والسابعة رقم التخصص.",
 "ماذا تعني الخانة الأولى من اليمين في رقم السطر؟","كم ساعة معتمدة يمثلها رقم سطر رسالة الماجستير التي تنتهي بـ 6؟","شو يعني رقم السطر؟"),
])
